def get_ims_lti_interop_catalog() -> List[ImsLtiInteropRecord]:
    """Return complete ims_lti_interop registry."""
    return REGISTRY_IMS_LTI_INTEROP


def query_ims_lti_interop_by_difficulty(difficulty_level: str) -> List[ImsLtiInteropRecord]:
    """Filter ims_lti_interop elements matching difficulty."""
    return [item for item in REGISTRY_IMS_LTI_INTEROP if item.difficulty == difficulty_level]


def calculate_ims_lti_interop_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_IMS_LTI_INTEROP)

